    /// Drops a file that contains these contents
    FileEq(&'a str, &'a str),
}
use self::ExpectedOut::*;

fn test_eval(source: &str, expected_out: ExpectedOut) {
    Playground::setup("test_eval", |dirs, _playground| {
        let actual = nu!(
            cwd: dirs.test(),
            source,
        );

        match expected_out {
            Eq(eq) => {
